-- Product Azure SQL Database schema, migration 0001 (initial schema)
-- Status: draft, not applied; D-26 chose Azure SQL for the first release.
-- Not applied to any database or environment. Generated by model/generate.mjs from model/logical-model.json, model
-- 0.1.0 (2026-11-22), canonical SHA-256 131d2568eb8923907e52c1a9352804de79037bbd82033fd4702e249ba7ab9f76. Do not edit
-- by hand: change the model and run "node model/generate.mjs write".
--
-- Binding: document 22, section 11 (Azure SQL Database). Names: document 20, section 3.5. Batches are separated by
-- GO, as sqlcmd and the usual migration runners read them; the runner decides transactions.
--
-- Holds: 69 tables, one per entity of the first release, adopted and proposed (61 temporal, 4 updatable ledger, 4
-- append-only ledger), 1706 columns, 67 unique constraints, 6 filtered unique indexes, 209 check constraints, 491
-- foreign keys and 1 view.
-- Leaves out: row-level security predicates and security policies (document 22, section 11.3), database principals
-- and permissions (section 11.1), ledger digest storage, the seed load and the migration runner, and the later
-- entities L01 to L05.
--
-- Rules applied:
--   1. Primary key Id uniqueidentifier with a NEWSEQUENTIALID() default. Created On and Modified On default to
--      SYSUTCDATETIME(); the API sets Modified On on update (no trigger here).
--   2. Required Y is NOT NULL. Required N and C (conditional) are NULL; the engine checks conditions.
--   3. Configuration keys are varchar(64) with the format check of document 22, section 11.1. Engine meanings are
--      varchar(32) with a check listing the contract values. Both compare with Latin1_General_BIN2, so the checks are
--      ordinal, like the engine (document 25, section 3.2). A meaning copy never stores a derived value (superseded,
--      missing).
--   4. A store-enforced key with an optional column is a filtered unique index that ignores rows where that column is
--      empty. It refuses the same rows as the matching Dataverse alternate key, which does not enforce uniqueness on
--      null values [S15]. The engine checks the rest (document 22, section 7). Keys marked "engine" have no
--      constraint.
--   5. History classes follow document 22, sections 2.3 and 11.2: system-versioned temporal tables for mutable rows
--      (61 tables), updatable ledger tables for C46, O08, O09 and O10, append-only ledger tables for C02, O14, O20
--      and O24.
--   6. A subject that can be one of several entities gets one nullable foreign key per kind, an exactly-one check and
--      a check that the set column matches Subject Kind (document 22, section 2.6).
--
-- WORKING DEFAULT (open design question 1). About 20 fixed engine meanings, all labels configurable. Every meaning
--   attribute reads one of these contracts, and a client renames, adds or hides labels only. On this binding every
--   meaning column is varchar(32) with a check constraint that lists its contract's values (document 22, section
--   11.1). If the answer is no, these columns become references to configuration rows.
--
-- Review points:
--   1. C01 Configuration Set, C02 Configuration Set Version and O05 Principal Reference need each other through NOT
--      NULL foreign keys (C01 Created By Principal -> O05; C01 Performed By Principal -> O05; C02 Created By
--      Principal -> O05; C02 Performed By Principal -> O05; C02 Configuration Set -> C01; C02 Instructed By -> O05;
--      O05 Configuration Set Version -> C02). SQL Server checks a foreign key at every statement and has no deferred
--      constraints, so the first rows of these tables cannot be inserted. The bootstrap of version 1 (document 21,
--      section 4.8) needs a way in, for example a conditional Configuration Set Version on O05. Open until the
--      migration runner is built; the model is unchanged.
--   2. NOT NULL self references (O05 Principal Reference / Created By Principal; O05 Principal Reference / Performed
--      By Principal): the first row must carry its own Id, given by the caller instead of the NEWSEQUENTIALID()
--      default.
--   3. UNVERIFIED here: foreign keys, check constraints, filtered unique indexes and json columns on ledger tables,
--      and ALTER TABLE ADD CONSTRAINT on a ledger table after it is created. They are to be checked on Azure SQL
--      before the migration runner is built.
--   4. Created By and Modified By (platform identity) have no column: document 22 says temporal or ledger history
--      records the database principal. Whether temporal history shows the principal of each version is UNVERIFIED
--      here. If it does not, the temporal tables need those two columns.
--   5. C46 Configuration Draft is an updatable ledger table (document 22). Documents 20 and 25 call it a plain
--      updatable table.
--   6. Record Number (C46, O02, O07, O09 and O11) is assigned by the engine. No sequence is created here.

-- -------------------------------------------------------------------------------------------------------------------
-- Schemas (document 22, section 11.1). security holds the row-level security predicate functions; none are in this draft.
-- -------------------------------------------------------------------------------------------------------------------
CREATE SCHEMA [config];
GO
CREATE SCHEMA [ops];
GO
CREATE SCHEMA [audit];
GO
CREATE SCHEMA [security];
GO

-- -------------------------------------------------------------------------------------------------------------------
-- C01 Configuration Set: configuration, adopted, release R1.
-- History class V (configuration versioned): system-versioned temporal table. Delete policy: retire.
-- -------------------------------------------------------------------------------------------------------------------
CREATE TABLE [config].[ConfigurationSet] (
    [Id] uniqueidentifier NOT NULL CONSTRAINT [DF_ConfigurationSet_Id] DEFAULT NEWSEQUENTIALID(),
    [Name] nvarchar(200) NOT NULL,
    [Description] nvarchar(max) NULL,
    [CreatedOn] datetime2(3) NOT NULL CONSTRAINT [DF_ConfigurationSet_CreatedOn] DEFAULT SYSUTCDATETIME(),
    [ModifiedOn] datetime2(3) NOT NULL CONSTRAINT [DF_ConfigurationSet_ModifiedOn] DEFAULT SYSUTCDATETIME(),
    [CreatedByPrincipalId] uniqueidentifier NOT NULL,
    [PerformedByPrincipalId] uniqueidentifier NOT NULL,
    [PerformedByActorKind] varchar(32) NOT NULL,
    [OnBehalfOfId] uniqueidentifier NULL, -- conditional
    [ClientApp] nvarchar(200) NULL,
    [ClientAppVerified] bit NOT NULL,
    [IsAICreated] bit NOT NULL,
    [EngineVersion] nvarchar(20) NOT NULL,
    [EngineCheckedOn] datetime2(3) NOT NULL,
    [SetKind] varchar(32) NOT NULL,
    [BasedOnPresetId] uniqueidentifier NULL,
    [IsInForce] bit NOT NULL,
    [CurrentVersionId] uniqueidentifier NULL,
    [CurrentVersionNumber] int NULL,
    [PresetKey] varchar(64) NULL, -- conditional
    [ProductRelease] nvarchar(20) NULL, -- conditional
    [PresetKind] varchar(32) NULL, -- conditional
    [ValidFrom] datetime2(7) GENERATED ALWAYS AS ROW START HIDDEN NOT NULL, -- period start
    [ValidTo] datetime2(7) GENERATED ALWAYS AS ROW END HIDDEN NOT NULL, -- period end
    PERIOD FOR SYSTEM_TIME ([ValidFrom], [ValidTo]),
    CONSTRAINT [PK_ConfigurationSet] PRIMARY KEY CLUSTERED ([Id]),
    CONSTRAINT [UQ_ConfigurationSet_Name] UNIQUE ([Name]), -- business key
    CONSTRAINT [CK_ConfigurationSet_PresetKey] CHECK (
        [PresetKey] NOT LIKE '%[^a-z0-9-]%' COLLATE Latin1_General_BIN2
        AND [PresetKey] LIKE '[a-z]%' COLLATE Latin1_General_BIN2
    ), -- configuration key format
    CONSTRAINT [CK_ConfigurationSet_PerformedByActorKind] CHECK ([PerformedByActorKind] COLLATE Latin1_General_BIN2 IN (
        'person', 'AI client for a person', 'agent identity', 'pipeline', 'approval runner', 'engine'
    )), -- contract actor-kind
    CONSTRAINT [CK_ConfigurationSet_SetKind] CHECK ([SetKind] COLLATE Latin1_General_BIN2 IN ('preset', 'working')), -- contract configuration-set-kind
    CONSTRAINT [CK_ConfigurationSet_PresetKind] CHECK ([PresetKind] COLLATE Latin1_General_BIN2 IN (
        'full', 'overlay'
    )) -- contract preset-kind
)
WITH (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [config].[ConfigurationSetHistory]));
GO
-- C01 alternate key Preset Key, enforced where PresetKey is set. Model: Presets only; empty on working sets.
--   Dataverse alternate keys do not enforce uniqueness on null values.
CREATE UNIQUE NONCLUSTERED INDEX [UQ_ConfigurationSet_PresetKey] ON [config].[ConfigurationSet] ([PresetKey])
    WHERE [PresetKey] IS NOT NULL;
GO

