-- -------------------------------------------------------------------------------------------------------------------
-- O09 Decision: operational, adopted, release R1.
-- History class F (freeze on final): updatable ledger table. Delete policy: never.
-- Superseded By has no column here. The view [ops].[DecisionCurrent] computes it, so a frozen decision is never
-- updated (document 22, sections 8.1 and 11.2).
-- -------------------------------------------------------------------------------------------------------------------
CREATE TABLE [ops].[Decision] (
    [Id] uniqueidentifier NOT NULL CONSTRAINT [DF_Decision_Id] DEFAULT NEWSEQUENTIALID(),
    [Name] nvarchar(200) NOT NULL,
    [Description] nvarchar(max) NULL,
    [CreatedOn] datetime2(3) NOT NULL CONSTRAINT [DF_Decision_CreatedOn] DEFAULT SYSUTCDATETIME(),
    [ModifiedOn] datetime2(3) NOT NULL CONSTRAINT [DF_Decision_ModifiedOn] DEFAULT SYSUTCDATETIME(),
    [CreatedByPrincipalId] uniqueidentifier NOT NULL,
    [PerformedByPrincipalId] uniqueidentifier NOT NULL,
    [PerformedByActorKind] varchar(32) NOT NULL,
    [OnBehalfOfId] uniqueidentifier NULL, -- conditional
    [ClientApp] nvarchar(200) NULL,
    [ClientAppVerified] bit NOT NULL,
    [IsAICreated] bit NOT NULL,
    [EngineVersion] nvarchar(20) NOT NULL,
    [EngineCheckedOn] datetime2(3) NOT NULL,
    [ConfigurationSetVersionId] uniqueidentifier NOT NULL,
    [RecordNumber] nvarchar(20) NOT NULL,
    [DecisionTypeId] uniqueidentifier NOT NULL,
    [SubjectKind] nvarchar(64) NOT NULL,
    [SubjectApplicationId] uniqueidentifier NULL, -- conditional
    [SubjectIntakeRequestId] uniqueidentifier NULL, -- conditional
    [SubjectChangeRequestId] uniqueidentifier NULL, -- conditional
    [SubjectDeploymentRecordId] uniqueidentifier NULL, -- conditional
    [SubjectComponentId] uniqueidentifier NULL, -- conditional
    [SubjectClaimId] uniqueidentifier NULL, -- conditional
    [SubjectConfigurationDraftId] uniqueidentifier NULL, -- conditional
    [Statement] nvarchar(500) NOT NULL,
    [Context] nvarchar(max) NULL,
    [OptionsConsidered] nvarchar(max) NULL, -- conditional
    [OutcomeId] uniqueidentifier NULL, -- conditional
    [Reason] nvarchar(max) NULL, -- conditional
    [StatusId] uniqueidentifier NOT NULL,
    [StatusMeaning] varchar(32) NOT NULL,
    [DeciderId] uniqueidentifier NULL, -- conditional
    [DecidedOn] datetime2(3) NULL, -- conditional
    [SupersedesId] uniqueidentifier NULL,
    [AmendsId] uniqueidentifier NULL,
    [ConfidenceId] uniqueidentifier NULL,
    CONSTRAINT [PK_Decision] PRIMARY KEY CLUSTERED ([Id]),
    CONSTRAINT [UQ_Decision_RecordNumber] UNIQUE ([RecordNumber]), -- business key
    CONSTRAINT [CK_Decision_PerformedByActorKind] CHECK ([PerformedByActorKind] COLLATE Latin1_General_BIN2 IN (
        'person', 'AI client for a person', 'agent identity', 'pipeline', 'approval runner', 'engine'
    )), -- contract actor-kind
    CONSTRAINT [CK_Decision_StatusMeaning] CHECK ([StatusMeaning] COLLATE Latin1_General_BIN2 IN (
        'proposed', 'accepted', 'rejected', 'withdrawn'
    )), -- contract decision-status
    -- Exactly one Subject column is set, and it matches Subject Kind
    CONSTRAINT [CK_Decision_ExactlyOne_SubjectApplicationId] CHECK (
        CASE WHEN [SubjectApplicationId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectIntakeRequestId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectChangeRequestId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectDeploymentRecordId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectComponentId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectClaimId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectConfigurationDraftId] IS NULL THEN 0 ELSE 1 END
        = 1
    ),
    -- The subject column that is set matches Subject Kind
    CONSTRAINT [CK_Decision_SubjectKind] CHECK (
        ([SubjectKind] = N'Business Application' AND [SubjectApplicationId] IS NOT NULL)
        OR ([SubjectKind] = N'Intake Request' AND [SubjectIntakeRequestId] IS NOT NULL)
        OR ([SubjectKind] = N'Change Request' AND [SubjectChangeRequestId] IS NOT NULL)
        OR ([SubjectKind] = N'Deployment Record' AND [SubjectDeploymentRecordId] IS NOT NULL)
        OR ([SubjectKind] = N'Technical Component' AND [SubjectComponentId] IS NOT NULL)
        OR ([SubjectKind] = N'Claim' AND [SubjectClaimId] IS NOT NULL)
        OR ([SubjectKind] = N'Configuration Draft' AND [SubjectConfigurationDraftId] IS NOT NULL)
    )
)
WITH (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [ops].[DecisionHistory]), LEDGER = ON);
GO

