-- -------------------------------------------------------------------------------------------------------------------
-- O18 Delivery Link: operational, adopted, release R1.
-- History class M (mutable with history): system-versioned temporal table. Delete policy: draft-only.
-- Checked by the engine, not by a constraint: business key Subject Kind + Subject Application + Subject Change
--   Request + Subject Intake Request + Link Kind + External Id (The subject plus Link Kind plus External Id, or Url
--   when there is no External Id. It spans optional columns, so the engine checks it).
-- -------------------------------------------------------------------------------------------------------------------
CREATE TABLE [ops].[DeliveryLink] (
    [Id] uniqueidentifier NOT NULL CONSTRAINT [DF_DeliveryLink_Id] DEFAULT NEWSEQUENTIALID(),
    [Name] nvarchar(200) NOT NULL,
    [Description] nvarchar(max) NULL,
    [CreatedOn] datetime2(3) NOT NULL CONSTRAINT [DF_DeliveryLink_CreatedOn] DEFAULT SYSUTCDATETIME(),
    [ModifiedOn] datetime2(3) NOT NULL CONSTRAINT [DF_DeliveryLink_ModifiedOn] DEFAULT SYSUTCDATETIME(),
    [CreatedByPrincipalId] uniqueidentifier NOT NULL,
    [PerformedByPrincipalId] uniqueidentifier NOT NULL,
    [PerformedByActorKind] varchar(32) NOT NULL,
    [OnBehalfOfId] uniqueidentifier NULL, -- conditional
    [ClientApp] nvarchar(200) NULL,
    [ClientAppVerified] bit NOT NULL,
    [IsAICreated] bit NOT NULL,
    [EngineVersion] nvarchar(20) NOT NULL,
    [EngineCheckedOn] datetime2(3) NOT NULL,
    [ConfigurationSetVersionId] uniqueidentifier NOT NULL,
    [SubjectKind] nvarchar(64) NOT NULL,
    [SubjectApplicationId] uniqueidentifier NULL, -- conditional
    [SubjectChangeRequestId] uniqueidentifier NULL, -- conditional
    [SubjectIntakeRequestId] uniqueidentifier NULL, -- conditional
    [LinkKindId] uniqueidentifier NOT NULL,
    [ExternalId] nvarchar(400) NULL,
    [Url] nvarchar(2000) NOT NULL,
    [Label] nvarchar(200) NOT NULL,
    [LinkedOn] datetime2(3) NOT NULL,
    [LastSeenOn] datetime2(3) NULL,
    [IsMoved] bit NOT NULL,
    [MovedToUrl] nvarchar(2000) NULL, -- conditional
    [ValidFrom] datetime2(7) GENERATED ALWAYS AS ROW START HIDDEN NOT NULL, -- period start
    [ValidTo] datetime2(7) GENERATED ALWAYS AS ROW END HIDDEN NOT NULL, -- period end
    PERIOD FOR SYSTEM_TIME ([ValidFrom], [ValidTo]),
    CONSTRAINT [PK_DeliveryLink] PRIMARY KEY CLUSTERED ([Id]),
    CONSTRAINT [CK_DeliveryLink_PerformedByActorKind] CHECK ([PerformedByActorKind] COLLATE Latin1_General_BIN2 IN (
        'person', 'AI client for a person', 'agent identity', 'pipeline', 'approval runner', 'engine'
    )), -- contract actor-kind
    -- Exactly one Subject column is set, and it matches Subject Kind
    CONSTRAINT [CK_DeliveryLink_ExactlyOne_SubjectApplicationId] CHECK (
        CASE WHEN [SubjectApplicationId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectChangeRequestId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectIntakeRequestId] IS NULL THEN 0 ELSE 1 END
        = 1
    ),
    -- The subject column that is set matches Subject Kind
    CONSTRAINT [CK_DeliveryLink_SubjectKind] CHECK (
        ([SubjectKind] = N'Business Application' AND [SubjectApplicationId] IS NOT NULL)
        OR ([SubjectKind] = N'Change Request' AND [SubjectChangeRequestId] IS NOT NULL)
        OR ([SubjectKind] = N'Intake Request' AND [SubjectIntakeRequestId] IS NOT NULL)
    )
)
WITH (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [ops].[DeliveryLinkHistory]));
GO

