    -- Exactly one Subject column is set, and it matches Subject Kind
    CONSTRAINT [CK_EvidenceLink_ExactlyOne_SubjectDecisionId] CHECK (
        CASE WHEN [SubjectDecisionId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectApprovalRecordId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectChangeRequestId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectDeploymentRecordId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectReviewId] IS NULL THEN 0 ELSE 1 END
        + CASE WHEN [SubjectClaimId] IS NULL THEN 0 ELSE 1 END
        = 1
    ),
    -- The subject column that is set matches Subject Kind
    CONSTRAINT [CK_EvidenceLink_SubjectKind] CHECK (
        ([SubjectKind] = N'Decision' AND [SubjectDecisionId] IS NOT NULL)
        OR ([SubjectKind] = N'Approval Record' AND [SubjectApprovalRecordId] IS NOT NULL)
        OR ([SubjectKind] = N'Change Request' AND [SubjectChangeRequestId] IS NOT NULL)
        OR ([SubjectKind] = N'Deployment Record' AND [SubjectDeploymentRecordId] IS NOT NULL)
        OR ([SubjectKind] = N'Review' AND [SubjectReviewId] IS NOT NULL)
        OR ([SubjectKind] = N'Claim' AND [SubjectClaimId] IS NOT NULL)
    )
)
WITH (LEDGER = ON (APPEND_ONLY = ON));
GO

