    [CreatedOn] datetime2(3) NOT NULL CONSTRAINT [DF_Review_CreatedOn] DEFAULT SYSUTCDATETIME(),
    [ModifiedOn] datetime2(3) NOT NULL CONSTRAINT [DF_Review_ModifiedOn] DEFAULT SYSUTCDATETIME(),
    [CreatedByPrincipalId] uniqueidentifier NOT NULL,
    [PerformedByPrincipalId] uniqueidentifier NOT NULL,
