    [OnBehalfOfId] uniqueidentifier NULL, -- conditional
    [ClientApp] nvarchar(200) NULL,
    [ClientAppVerified] bit NOT NULL,
    [IsAICreated] bit NOT NULL,
    [EngineVersion] nvarchar(20) NOT NULL,
    [EngineCheckedOn] datetime2(3) NOT NULL,
    [ConfigurationSetVersionId] uniqueidentifier NOT NULL,
    [BusinessApplicationId] uniqueidentifier NOT NULL,
    [ReviewTypeId] uniqueidentifier NOT NULL,
    [StatusId] uniqueidentifier NOT NULL,
    [StatusMeaning] varchar(32) NOT NULL,
    [Trigger] varchar(32) NOT NULL,
    [DueOn] date NOT NULL,
    [DoneOn] date NULL, -- conditional
    [ReviewerId] uniqueidentifier NULL, -- conditional
    [OutcomeDecisionId] uniqueidentifier NULL, -- conditional
    [NextDueOn] date NULL,
    [ValidFrom] datetime2(7) GENERATED ALWAYS AS ROW START HIDDEN NOT NULL, -- period start
    [ValidTo] datetime2(7) GENERATED ALWAYS AS ROW END HIDDEN NOT NULL, -- period end
    PERIOD FOR SYSTEM_TIME ([ValidFrom], [ValidTo]),
    CONSTRAINT [PK_Review] PRIMARY KEY CLUSTERED ([Id]),
    CONSTRAINT [UQ_Review_BusinessApplicationId_ReviewTypeId_DueOn] UNIQUE ([BusinessApplicationId], [ReviewTypeId], [DueOn]), -- business key
    CONSTRAINT [CK_Review_PerformedByActorKind] CHECK ([PerformedByActorKind] COLLATE Latin1_General_BIN2 IN (
        'person', 'AI client for a person', 'agent identity', 'pipeline', 'approval runner', 'engine'
    )), -- contract actor-kind
