    CONSTRAINT [CK_Review_Trigger] CHECK ([Trigger] COLLATE Latin1_General_BIN2 IN (
        'cadence', 'tier answer trigger', 'owner check', 'request'
    )) -- contract review-trigger
)
WITH (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [ops].[ReviewHistory]));
