-- -------------------------------------------------------------------------------------------------------------------
-- O09 Decision: Superseded By is derived from the later decision's Supersedes link, so the frozen row is never
-- updated (document 22, section 8.1). One decision is superseded by at most one accepted decision (an engine rule,
-- R70).
-- -------------------------------------------------------------------------------------------------------------------
CREATE VIEW [ops].[DecisionCurrent]
AS
SELECT
    d.[Id],
    d.[Name],
    d.[Description],
    d.[CreatedOn],
    d.[ModifiedOn],
    d.[CreatedByPrincipalId],
    d.[PerformedByPrincipalId],
    d.[PerformedByActorKind],
    d.[OnBehalfOfId],
    d.[ClientApp],
    d.[ClientAppVerified],
    d.[IsAICreated],
    d.[EngineVersion],
    d.[EngineCheckedOn],
    d.[ConfigurationSetVersionId],
    d.[RecordNumber],
    d.[DecisionTypeId],
    d.[SubjectKind],
    d.[SubjectApplicationId],
    d.[SubjectIntakeRequestId],
    d.[SubjectChangeRequestId],
    d.[SubjectDeploymentRecordId],
    d.[SubjectComponentId],
    d.[SubjectClaimId],
    d.[SubjectConfigurationDraftId],
    d.[Statement],
    d.[Context],
    d.[OptionsConsidered],
    d.[OutcomeId],
    d.[Reason],
    d.[StatusId],
    d.[StatusMeaning],
    d.[DeciderId],
    d.[DecidedOn],
    d.[SupersedesId],
    d.[AmendsId],
    d.[ConfidenceId],
    s.[Id] AS [SupersededById]
FROM [ops].[Decision] AS d
OUTER APPLY (
    SELECT TOP (1) n.[Id]
    FROM [ops].[Decision] AS n
    WHERE n.[SupersedesId] = d.[Id] AND n.[StatusMeaning] = 'accepted'
    ORDER BY n.[Id]
) AS s;
GO

